19	def json_response_bytes(value):
20	    """Serialize value to UTF-8 JSON bytes, never failing on a lone surrogate.
21	
22	    Survey content is validated (unpaired surrogates rejected) before it gets
23	    here; escaping any stray surrogate as ``\\uXXXX`` is only a safety net so
24	    an unexpected error response can never abort mid-write and leave the
25	    caller with a dropped connection instead of parseable JSON.
26	    """
27	    text = json.dumps(value, ensure_ascii=False)
28	    text = "".join(
29	        f"\\u{ord(ch):04x}" if 0xD800 <= ord(ch) <= 0xDFFF else ch
30	        for ch in text
31	    )
32	    return text.encode("utf8")
