799	function editableSurveyFromRead(data, expectedId) {
800	  if (!data || typeof data !== "object" || Array.isArray(data)) return null;
801	  if (data.id !== expectedId) return null;
802	  if (typeof data.title !== "string") return null;
803	  if (typeof data.description !== "string") return null;
804	  if (!Array.isArray(data.questions)) return null;
805	  for (const question of data.questions) {
806	    if (!question || typeof question !== "object" || Array.isArray(question)) return null;
807	    if (typeof question.title !== "string") return null;
808	    if (question.type !== "text" && question.type !== "single_choice") return null;
809	    if (typeof question.required !== "boolean") return null;
810	    if (!Array.isArray(question.options)) return null;
811	    for (const option of question.options) {
812	      if (typeof option !== "string") return null;
813	    }
814	    if (question.type === "single_choice" && question.options.length < 2) return null;
815	    if (question.type === "text" && question.options.length !== 0) return null;
816	  }
817	  return data;
818	}
