885	def contains_unpaired_surrogate(text):
886	    """True if text holds an unpaired UTF-16 surrogate code point (U+D800..U+DFFF).
887	
888	    A syntactically legal JSON body can still contain one via an unpaired
889	    ``\\uD800``/``\\uDC00`` escape. Such a code point cannot be encoded as
890	    UTF-8, so it must be rejected as a content error of the specific field
891	    before saving: otherwise encoding the response later aborts the request
892	    without returning the validation result the caller expects. Correctly
893	    paired escapes decode to a single astral character (e.g. an emoji) and
894	    never match this check.
895	    """
896	    return any(0xD800 <= ord(ch) <= 0xDFFF for ch in text)
897	
898	
899	def surrogate_content_error(field_label, text):
900	    """Build a 400 message naming the field that holds an unpaired surrogate.
901	
902	    The offending code point is shown as U+XXXX instead of embedding the
903	    broken character, so the error message itself is always UTF-8 encodable
904	    and the error response stays parseable JSON.
905	    """
906	    for ch in text:
907	        if 0xD800 <= ord(ch) <= 0xDFFF:
908	            return (
909	                f"{field_label}包含无法编码保存的字符"
910	                f"（未配对的 Unicode 代理码点 U+{ord(ch):04X}），"
911	                f"请删除或修改该字符后重试"
912	            )
913	    raise AssertionError("text contains no unpaired surrogate")
914	
915	
916	def safe_quote_json_string(text):
917	    """Return a JSON-quoted form of text with lone surrogates escaped.
918	
919	    Behaves like ``json.dumps(text, ensure_ascii=False)`` but renders each
920	    unpaired surrogate as ``\\uXXXX`` so the result is always valid,
921	    UTF-8-encodable JSON. Used when echoing caller-provided strings inside an
922	    error message, where the raw character would break error encoding.
923	    """
924	    quoted = json.dumps(text, ensure_ascii=False)
925	    return "".join(
926	        f"\\u{ord(ch):04x}" if 0xD800 <= ord(ch) <= 0xDFFF else ch
927	        for ch in quoted
928	    )
