931	def validate_survey(obj):
932	    """Validate a decoded survey payload.
933	
934	    Returns (clean_survey, None) on success or (None, error_message) on failure.
935	    Strings are stored trimmed of surrounding whitespace; description keeps its
936	    raw value so Chinese, quotes and newlines are preserved.
937	    """
938	    if not isinstance(obj, dict):
939	        return None, "请求体必须是 JSON 对象"
940	    if "title" not in obj:
941	        return None, "缺少字段 title"
942	    title = obj["title"]
943	    if not isinstance(title, str):
944	        return None, "title 必须是字符串"
945	    if contains_unpaired_surrogate(title):
946	        return None, surrogate_content_error("问卷标题", title)
947	    title = title.strip()
948	    if not title:
949	        return None, "title 不能为空（或全为空白字符）"
950	
951	    description = obj.get("description", "")
952	    if not isinstance(description, str):
953	        return None, "description 必须是字符串"
954	    if contains_unpaired_surrogate(description):
955	        return None, surrogate_content_error("问卷说明", description)
956	
957	    if "questions" not in obj:
958	        return None, "缺少字段 questions"
959	    raw_questions = obj["questions"]
960	    if not isinstance(raw_questions, list):
961	        return None, "questions 必须是数组"
962	    if len(raw_questions) == 0:
963	        return None, "questions 至少需要一道题"
964	
965	    questions = []
966	    for index, raw_question in enumerate(raw_questions, start=1):
967	        location = f"第 {index} 题"
968	        if not isinstance(raw_question, dict):
969	            return None, f"{location}（questions[{index - 1}]）必须是对象"
970	
971	        if "type" not in raw_question:
972	            return None, f"{location}：缺少字段 type"
973	        question_type = raw_question["type"]
974	        if not isinstance(question_type, str):
975	            return None, f"{location}：type 必须是字符串"
976	        if question_type not in QUESTION_TYPES:
977	            # 不能把未配对的代理码点直接拼进错误信息，否则错误响应自身无法
978	            # 编码、会再次中断请求；safe_quote_json_string 只转义代理码点。
979	            shown = safe_quote_json_string(question_type)
980	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
981	
982	        if "title" not in raw_question:
983	            return None, f"{location}：缺少字段 title"
984	        question_title = raw_question["title"]
985	        if not isinstance(question_title, str):
986	            return None, f"{location}：title 必须是字符串"
987	        if contains_unpaired_surrogate(question_title):
988	            return None, surrogate_content_error(f"{location}的题目标题", question_title)
989	        question_title = question_title.strip()
990	        if not question_title:
991	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
992	
993	        required = raw_question.get("required", False)
994	        if not isinstance(required, bool):
995	            return None, f"{location}：required 必须是布尔值"
996	
997	        raw_options = raw_question.get("options", [])
998	        if not isinstance(raw_options, list):
999	            return None, f"{location}：options 必须是数组"
1000	
1001	        options = []
1002	        if question_type == "text":
1003	            if len(raw_options) > 0:
1004	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
1005	        else:
1006	            if len(raw_options) < 2:
1007	                return None, f"{location}：单选题至少需要两个选项"
1008	            seen = set()
1009	            for option_index, raw_option in enumerate(raw_options, start=1):
1010	                if not isinstance(raw_option, str):
1011	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
1012	                if contains_unpaired_surrogate(raw_option):
1013	                    field_label = f"{location}的第 {option_index} 个选项"
1014	                    return None, surrogate_content_error(field_label, raw_option)
1015	                option = raw_option.strip()
1016	                if not option:
1017	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
1018	                if option in seen:
1019	                    shown = safe_quote_json_string(option)
1020	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
1021	                seen.add(option)
1022	                options.append(option)
1023	
1024	        questions.append({
1025	            "type": question_type,
1026	            "title": question_title,
1027	            "required": required,
1028	            "options": options,
1029	        })
1030	
1031	    return {
1032	        "title": title,
1033	        "description": description,
1034	        "questions": questions,
1035	    }, None
