1038	def main():
1039	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
1040	    commands = parser.add_subparsers(dest="command", required=True)
1041	    serve = commands.add_parser("serve", help="Start the HTTP service")
1042	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
1043	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
1044	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
1045	    args = parser.parse_args()
1046	    if not 0 <= args.port <= 65535:
1047	        parser.error("port must be between 0 and 65535")
1048	    args.data_dir.mkdir(parents=True, exist_ok=True)
1049	    # 每个连接由独立线程处理（见下方 ThreadingHTTPServer），因此数据库连接
1050	    # 会被多个线程共享：check_same_thread=False 允许跨线程使用，所有读写再
1051	    # 经 db_lock 串行化，保证一次保存/替换内部的多条语句仍然原子生效。
1052	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite", check_same_thread=False)
1053	    db_lock = threading.Lock()
1054	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
1055	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
1056	    if "description" not in columns:
1057	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
1058	    database.execute(
1059	        "CREATE TABLE IF NOT EXISTS questions ("
1060	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
1061	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
1062	    )
1063	    database.execute(
1064	        "CREATE TABLE IF NOT EXISTS question_options ("
1065	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
1066	    )
1067	    database.commit()
