    # ---------- 加载失败：服务端返回失败 ----------

    def test_server_error_shows_retry_and_back_without_form_or_data_change(self):
        """服务端 500：明确提示加载失败、提供重试/返回详情，不进表单，草稿原样保留。"""
        survey_id, saved = self.standard_survey()
