      status.textContent = `问卷 #${id} 不存在。`;
      return;
    }
    if (!resp.ok) {
      status.textContent = `详情加载失败（HTTP ${resp.status}），请稍后重试。`;
      return;
    }
    survey = await resp.json();
  } catch (err) {
    if (view !== activeView) return;
    status.textContent = `详情加载失败：${err}`;
    return;
  }
  if (view !== activeView) return;

  app.replaceChildren(
    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
